export function getRandomQuestions(count: number = 25): Question[] {
  const shuffled = [...questions].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

export function getQuestionsByCategory(category: CategoryKey): Question[] {
  return questions.filter(q => q.category === category);
}

export function getQuestionsByCategories(categories: CategoryKey[]): Question[] {
  return questions.filter(q => categories.includes(q.category as CategoryKey));
}

export function getCategoryStats(): Record<CategoryKey, number> {
  const stats = {} as Record<CategoryKey, number>;
  for (const key of Object.keys(categories) as CategoryKey[]) {
    stats[key] = questions.filter(q => q.category === key).length;
  }
  return stats;
}